\begin{theorem}\label{theo:hierarchical-if}
	Let $\sigma$ be a schema. For every HCQ $Q$ over $\sigma$, there exists a \acrocea $\ACH_Q$ over $\sigma$ with unary predicates in $\uncq$ and binary predicates in $\bincq$ such that $\ACH_Q \equiv Q$. Furthermore, $\ACH_Q$ is unambiguous and \changed{of at most} exponential size with respect to $Q$. If $Q$ does not have self joins, then $\ACH_Q$ is of \changed{quadratic}~size. %
\end{theorem}
