\subsection*{Proof of Proposition~\ref{prop:pcea-expressive}}
\begin{proof}
	To prove this statement we just need to find a \anamecea $\ACH$ with no CCEA equivalent, i.e. there is no CCEA $\cC$ such that $\sem{\ACH}(\Stream) = \sem{\cC}(\Stream)$ for every stream~$\Stream$.
	\changed{Let $\ACH$ be the \acrocea represented in Figure~\ref{fig:ex-proof}, then }$\ACH = \big(Q, \un, \bin, \Omega, \Delta, F \big)$, with $Q = \{R(x, y), S(x, y), T(x), x, y\}$, $\Omega = \{R, S, T\}$, $F=\{x\}$ and:
	\[
	\begin{array}{rcl}
	\Delta & = & \big\{ (\emptyset, U_{R(x, y)}, \emptyset, \{R(x, y)\}, R(x, y)), \\
		& &(\emptyset, U_{S(x, y)}, \emptyset, \{S(x, y)\}, S(x, y)), \\
		& &(\emptyset, U_{T(x)}, \emptyset, \{T(x)\}, T(x)), \\
		& &(\{R(x, y), T(x)\}, U_{S(x, y)}, \{(R(x, y), B_{R(x, y), S(x, y)}), (T(x), B_{T(x), S(x, y)})\}, \{S(x, y)\}, x), \\
		& &(\{S(x, y), T(x)\}, U_{R(x, y)}, \{(S(x, y), B_{S(x, y), R(x, y)}), (T(x),B_{T(x), R(x, y)})\}, \{R(x, y)\}, x),  \\   
		& &(\{R(x, y)\}, U_{S(x, y)}, \{(R(x, y), B_{R(x, y), S(x, y)})\}, \{S(x, y)\}, y), \\
		& &(\{S(x, y)\}, U_{R(x, y)}, \{(S(x, y), B_{S(x, y), R(x, y)})\}, \{R(x, y)\}, y), \\
		& &(\{y\}, U_{T(x)}, \{(y, B_{y, T(x, y)})\}, \{T(x)\}, x) \big\}
	\end{array}
	\]
	with the predicates $U_{R(\bar{x})}$ and $B_{R(\bar{x}), S(\bar{y})}$ defined as:
	\[
		U_{R(\bar{x})} \ := \  \{R(\bar{a}) \in \tuples[\Schema] \mid \exists h \in \Hom.\; h(R(\bar{x})) = R(\bar{a})\}
	\]
	and:
	\[
		B_{R(\bar{x}), S(\bar{y})} \ := \ \{(R(\bar{a}), S(\bar{b})) \mid \exists h \in \Hom.\; h(R(\bar{x})) = R(\bar{a}) \wedge h(S(\bar{y})) = S(\bar{b})\}.
	\]

	Let $\Stream_i = \bleft R(0, i), T(0), S(0, i), \ldots \bright$ be a family of streams over the set of data values $\Data=\nat$ with $i \in \nat$. It is clear that the valuation $\bleft 0, 1, 2\bright \in \sem{\ACH}(\Stream_i)$ for every $i \in \nat$.
	Let $\cC = (Q', \un', \bin', \Omega', \Delta', I', F')$ be a deterministic CCEA such that $\sem{\CHCEA}(\Stream_i) = \sem{\ACH}(\Stream_i)$ for every $i \in \nat$. This means that for every stream $\Stream_i$, there is an accepting run of $\CHCEA$ over of the form $\rho_i: q_{i, 0} \xrightarrow{R(0, i)} q_{i, 1} \xrightarrow{T(0)} q_{i, 2} \xrightarrow{S(0, i)} q_{i, 3}$.

	Since $\cC$ has a finite number of states, we know that there must be two streams, $\Stream_j$ and $\Stream_k$ with $j \neq k$ with accepting runs $\rho_j: q_{j, 0} \xrightarrow{R(0, j)} q_{j, 1} \xrightarrow{T(0)} q_{j, 2} \xrightarrow{S(0, j)} q_{j, 3}$ and $\rho_k: q_{k, 0} \xrightarrow{R(0, k)} q_{k, 1} \xrightarrow{T(0)} q_{k, 2} \xrightarrow{S(0, k)} q_{k, 3}$, respectively, such that $q_{j, i} = q_{k, i}$ for every $0 \leq i \leq 3$.

	Given the run $\rho_k$ of $\cC$, we know that there must be a transition $(q_{k, 2}, U, B, \omega, q_{k, 3})\in \Delta'$ such that $S(0, k) \in U$ and $(T(0), S(0, k)) \in B$ and since $q_{k, 2} = q_{j, 2}$ and $q_{k, 3} = q_{j, 3}$ the following will be an accepting run of $\cC$ over the stream $S_{j, k} = \{\{ R(0, j), T(0), S(0, k)\}\}$: $\rho_{j, k}: q_{j, 0} \xrightarrow{R(0, j)} q_{j, 1} \xrightarrow{T(0)} q_{j, 2} \xrightarrow{S(0, k)} q_{j, 3}$.

	We can easily check that there are no accepting runs of $\ACH$ over $\Stream_{j, k}$, meaning $\sem{\ACH}(\Stream_{j, k}) \neq \sem{\cC}(\Stream_{j, k})$ and therefore there is no CCEA $\cC$ such that $\sem{\ACH}(\Stream) = \sem{\cC}(\Stream)$ for every stream~$\Stream$.
\end{proof} 	
